-- Pilot curricula: ten original courses, each with four chapters and twelve
-- lessons. The first two lessons are free previews; all other lesson content
-- is protected by can_access_lesson() until a course purchase/subscription.
-- Courses stay in draft until the admin supplies a real price, cover, review,
-- and rights confirmation in the course editor.
do $pilot$
declare
  v_catalog jsonb := $catalog$
[
  {"code":"AI-01","subtitle":"Comprendre et utiliser l’IA générative dans les tâches du quotidien.","description":"Un parcours pratique pour choisir les bons usages de l’intelligence artificielle, formuler des demandes utiles et vérifier les résultats avant de les utiliser.","outcomes":["Repérer les tâches où l’IA apporte un gain concret.","Rédiger et améliorer une consigne structurée.","Vérifier les réponses et protéger les informations sensibles.","Construire un petit flux de travail assisté par l’IA."],"prerequisites":"Aucune expérience en programmation n’est nécessaire. Disposer d’un accès à un outil d’IA générative est utile pour les exercices.","chapters":[
    {"title":"Comprendre l’IA générative","description":"Découvrir les capacités, les limites et les bons réflexes de départ.","lessons":[["Ce que fait un assistant IA","Distinguer génération de texte, recherche d’information et automatisation, puis choisir une tâche adaptée."],["Préparer un premier échange utile","Définir un objectif, donner le contexte nécessaire et préciser la forme du résultat attendu."],["Repérer une réponse incertaine","Identifier les affirmations à contrôler et retrouver une source fiable avant de les réutiliser."]]},{"title":"Formuler de bonnes consignes","description":"Transformer une demande vague en consigne claire et vérifiable.","lessons":[["Structurer une consigne","Assembler rôle, contexte, tâche, contraintes et format de sortie dans une demande réutilisable."],["Améliorer une réponse par étapes","Demander une première version, relever les écarts et guider une révision ciblée."],["Adapter le ton et le format","Faire produire une réponse destinée à un lecteur et à un canal précis."]]},{"title":"Appliquer l’IA à ses tâches","description":"Utiliser l’assistant pour rédiger, organiser et analyser avec méthode.","lessons":[["Préparer un document de travail","Passer de notes désordonnées à un plan, puis contrôler que les idées importantes sont conservées."],["Résumer sans perdre le sens","Définir le public, la longueur et les éléments à préserver dans un résumé."],["Créer une routine assistée","Assembler plusieurs demandes simples et prévoir un contrôle humain à chaque étape."]]},{"title":"Réaliser un mini-projet responsable","description":"Construire un cas d’usage utile et documenter ses vérifications.","lessons":[["Choisir un cas d’usage mesurable","Évaluer le temps gagné, le risque d’erreur et les données nécessaires avant de commencer."],["Tester et améliorer son flux","Comparer le résultat initial et le résultat révisé avec une grille de critères."],["Projet : assistant de travail personnel","Produire un flux documenté pour une tâche réelle, avec consignes, limites et contrôles." ]]}
  ]},
  {"code":"DEV-01","subtitle":"Acquérir les repères essentiels pour comprendre et construire un site web.","description":"Un parcours débutant qui relie les bases de l’informatique, le fonctionnement du web, la logique de programmation et les premières étapes d’un projet web.","outcomes":["Expliquer le rôle du navigateur, du serveur et d’une URL.","Décomposer un problème en instructions simples.","Lire une structure HTML et repérer les styles CSS de base.","Organiser et publier un premier mini-projet web."],"prerequisites":"Aucun prérequis technique. Un ordinateur et un navigateur web suffisent pour commencer.","chapters":[
    {"title":"Repères informatiques et web","description":"Comprendre les composants et le vocabulaire d’un projet numérique.","lessons":[["Fichiers, dossiers et formats","Reconnaître les fichiers, extensions et répertoires utilisés dans un projet."],["Comment une page arrive au navigateur","Suivre le parcours d’une requête entre navigateur, serveur, DNS et réponse web."],["Lire une adresse web","Identifier protocole, domaine, chemin et paramètres dans une URL."]]},{"title":"Raisonner comme un développeur","description":"Passer d’un besoin à une suite d’étapes testables.","lessons":[["Décomposer un problème","Écrire les entrées, transformations et sorties avant de choisir une solution."],["Variables, conditions et répétitions","Comprendre les trois mécanismes qui structurent un algorithme simple."],["Dessiner un algorithme","Représenter un petit traitement sous forme de pseudo-code et vérifier ses cas limites."]]},{"title":"Les briques d’une page web","description":"Découvrir le rôle de HTML, CSS et JavaScript.","lessons":[["Structurer une page en HTML","Organiser titres, paragraphes, liens et listes dans une structure lisible."],["Mettre en forme avec CSS","Relier une feuille de styles et modifier couleurs, espacements et disposition."],["Séparer contenu, style et comportement","Identifier quelle technologie répond à chaque changement demandé."]]},{"title":"Construire et présenter un mini-site","description":"Assembler les bases dans un petit livrable cohérent.","lessons":[["Planifier les pages d’un site","Définir une audience, un objectif et les pages nécessaires à une première version."],["Contrôler l’affichage et les liens","Tester navigation, lisibilité, adaptation mobile et erreurs de chargement."],["Projet : page de présentation","Créer une page personnelle structurée, stylée et accompagnée d’un court guide de lancement."]]}
  ]},
  {"code":"DES-01","subtitle":"Maîtriser les principes visuels pour créer des supports clairs et cohérents.","description":"Une introduction pratique au design graphique : hiérarchie, typographie, couleurs, composition et réalisation d’un visuel prêt à être diffusé.","outcomes":["Construire une hiérarchie visuelle lisible.","Associer typographies et couleurs avec cohérence.","Composer un visuel adapté à son format et à son public.","Présenter un fichier final propre et exporté au bon format."],"prerequisites":"Aucun prérequis. Un outil de création graphique, même gratuit, suffit pour les exercices.","chapters":[
    {"title":"Observer et organiser l’information","description":"Partir du message avant de choisir les éléments graphiques.","lessons":[["Définir le message d’un visuel","Formuler une idée principale et identifier les informations secondaires."],["Créer une hiérarchie visuelle","Utiliser taille, contraste et position pour guider le regard."],["Analyser un support existant","Évaluer lisibilité, ordre de lecture et adéquation au public."]]},{"title":"Typographie et couleur","description":"Choisir des systèmes graphiques lisibles et reproductibles.","lessons":[["Choisir et associer des caractères","Comparer lisibilité, personnalité et rôle des familles typographiques."],["Construire une palette utile","Créer une palette limitée avec couleurs principales, secondaires et d’accent."],["Vérifier les contrastes","Contrôler la lisibilité du texte et ajuster les combinaisons de couleurs."]]},{"title":"Composition et formats","description":"Placer les éléments et adapter une création aux supports.","lessons":[["Utiliser grilles et alignements","Organiser les blocs avec marges, colonnes et repères communs."],["Gérer images et espace négatif","Équilibrer densité, respiration et rôle des images."],["Décliner un visuel","Adapter une composition à plusieurs formats sans perdre son message."]]},{"title":"Finaliser un support graphique","description":"Préparer un fichier contrôlé pour son usage réel.","lessons":[["Préparer les ressources","Vérifier droits, résolution, dimensions et cohérence des fichiers importés."],["Faire une revue de qualité","Relire textes, alignements, contrastes et zones de sécurité avant export."],["Projet : visuel de campagne","Créer une affiche et une déclinaison sociale, puis expliquer les choix de composition."]]}
  ]},
  {"code":"MKT-01","subtitle":"Poser les bases d’une stratégie de marketing numérique mesurable.","description":"Apprendre à définir son public, choisir les bons canaux, construire un message cohérent et suivre des indicateurs utiles pour améliorer une campagne.","outcomes":["Décrire une audience et son besoin prioritaire.","Choisir des canaux cohérents avec un objectif marketing.","Construire un message et un parcours de conversion simples.","Lire quelques indicateurs et proposer une amélioration."],"prerequisites":"Aucun prérequis. Venir avec une idée d’activité, de produit ou de projet à promouvoir est recommandé.","chapters":[
    {"title":"Fondations et objectifs marketing","description":"Relier les objectifs de l’activité aux attentes d’un public précis.","lessons":[["Définir un objectif mesurable","Transformer une intention générale en résultat suivi dans un délai défini."],["Comprendre son audience","Décrire besoins, freins, contexte et critères de choix d’un client cible."],["Cartographier le parcours client","Repérer les étapes entre découverte, comparaison, achat et fidélisation."]]},{"title":"Message et présence numérique","description":"Construire une proposition claire et une présence cohérente.","lessons":[["Formuler une proposition de valeur","Expliquer pour qui l’offre est conçue, quel problème elle résout et en quoi elle aide."],["Choisir les canaux de communication","Comparer réseaux sociaux, site, e-mail et recherche selon l’audience et le but."],["Créer un calendrier éditorial","Planifier des thèmes, formats, fréquences et appels à l’action réalistes."]]},{"title":"Acquisition et conversion","description":"Attirer une audience pertinente et l’aider à passer à l’action.","lessons":[["Comprendre les bases du référencement","Relier intention de recherche, contenu utile et structure d’une page."],["Écrire un appel à l’action","Rendre l’action attendue explicite et cohérente avec la promesse du contenu."],["Construire une page de campagne","Organiser promesse, bénéfices, preuves disponibles et prochaine étape."]]},{"title":"Mesurer et améliorer","description":"Lire les résultats sans confondre activité et impact.","lessons":[["Choisir des indicateurs utiles","Associer chaque objectif à une mesure et à une source de données."],["Analyser un tableau de campagne","Comparer période, canal et résultats pour formuler une hypothèse d’amélioration."],["Projet : plan marketing de lancement","Préparer une campagne courte avec audience, message, canaux, calendrier et indicateurs."]]}
  ]},
  {"code":"VID-01","subtitle":"Tourner et monter des vidéos de qualité avec un smartphone.","description":"Un parcours pratique pour préparer un tournage mobile, cadrer une image stable, enregistrer un son compréhensible et livrer une vidéo adaptée à sa plateforme.","outcomes":["Préparer un plan de tournage court.","Régler lumière, cadrage et stabilité avec un téléphone.","Enregistrer une voix intelligible dans un environnement adapté.","Monter et exporter une vidéo aux bons formats."],"prerequisites":"Aucun prérequis. Un smartphone avec caméra et un espace de stockage disponible sont nécessaires.","chapters":[
    {"title":"Préparer une vidéo","description":"Définir le message, le format et les plans avant le tournage.","lessons":[["Clarifier l’objectif et le public","Choisir l’idée principale, la durée et la plateforme de diffusion."],["Écrire un mini-script","Organiser une accroche, quelques points essentiels et une conclusion."],["Préparer une liste de plans","Découper le script en images et prévoir lieux, accessoires et transitions."]]},{"title":"Image, lumière et stabilité","description":"Obtenir des images lisibles avec le matériel disponible.","lessons":[["Choisir le cadrage","Utiliser orientation, hauteur et espace autour du sujet pour servir le message."],["Maîtriser la lumière disponible","Placer le sujet par rapport aux fenêtres et éviter les contre-jours gênants."],["Stabiliser le téléphone","Choisir une prise en main, un support et un mouvement adaptés à chaque plan."]]},{"title":"Son et montage","description":"Capturer une voix claire et assembler une séquence compréhensible.","lessons":[["Enregistrer une voix intelligible","Réduire le bruit, placer le micro et contrôler le niveau avant la prise."],["Monter une séquence courte","Sélectionner les prises, couper les longueurs et garder un rythme adapté."],["Ajouter titres et sous-titres","Rendre les informations clés visibles et vérifier la lisibilité sur petit écran."]]},{"title":"Exporter et publier","description":"Contrôler le fichier final et adapter sa diffusion.","lessons":[["Choisir un format d’export","Adapter dimensions, fréquence et compression à la plateforme de diffusion."],["Faire le contrôle final","Vérifier image, son, textes, droits des médias et lecture sur téléphone."],["Projet : vidéo verticale de présentation","Réaliser une vidéo courte avec script, plans, montage, sous-titres et fiche d’export."]]}
  ]},
  {"code":"BUR-01","subtitle":"Créer et mettre en forme des documents professionnels avec Microsoft Word.","description":"Découvrir une méthode de travail fiable dans Word : structurer un document avec les styles, maîtriser la mise en page, collaborer et préparer un fichier accessible à partager.","outcomes":["Structurer un document avec titres et styles cohérents.","Gérer sections, pages, tableaux et éléments visuels.","Utiliser commentaires et suivi des modifications.","Vérifier puis exporter un document professionnel."],"prerequisites":"Savoir utiliser un ordinateur et ouvrir un document. Microsoft Word ou un logiciel compatible est requis pour suivre les démonstrations.","chapters":[
    {"title":"Créer une structure propre","description":"Partir d’un document organisé plutôt que de mises en forme manuelles.","lessons":[["Découvrir l’espace de travail","Repérer ruban, document, styles et commandes utiles sans multiplier les clics."],["Appliquer les styles de titre","Créer une hiérarchie de titres réutilisable et adaptée à la navigation."],["Construire un plan automatique","Générer et mettre à jour une table des matières depuis les styles."]]},{"title":"Mise en page et éléments","description":"Contrôler pages, sections, tableaux et illustrations.","lessons":[["Régler marges et orientation","Choisir les dimensions et l’orientation en fonction du document final."],["Insérer un tableau lisible","Organiser des données avec en-têtes, alignements et largeurs cohérents."],["Gérer images et légendes","Positionner une image, régler l’habillage et ajouter une description utile."]]},{"title":"Révision et collaboration","description":"Relire efficacement et conserver une trace des changements.","lessons":[["Utiliser commentaires et révisions","Annoter un passage et activer le suivi des modifications pour une revue partagée."],["Créer en-têtes et pieds de page","Insérer pagination et informations répétées au bon niveau de section."],["Vérifier l’accessibilité","Contrôler titres, liens, tableaux et textes alternatifs avant partage."]]},{"title":"Finaliser un document professionnel","description":"Assembler une mise en page stable et produire les bons formats.","lessons":[["Préparer une lettre ou un rapport","Choisir une structure adaptée au destinataire, au but et au niveau de détail."],["Contrôler la cohérence du fichier","Relire styles, numérotation, sauts de page, liens et métadonnées visibles."],["Projet : rapport de synthèse","Produire un rapport structuré avec page de titre, table des matières, tableau et export PDF."]]}
  ]},
  {"code":"DAT-01","subtitle":"Transformer un tableau brut en analyse claire et décisions argumentées.","description":"Une introduction à l’analyse de données avec tableur : nettoyer un jeu de données, calculer des indicateurs, visualiser des tendances et présenter une conclusion vérifiable.","outcomes":["Contrôler la qualité d’un tableau de données.","Nettoyer et organiser les colonnes pour l’analyse.","Calculer des indicateurs descriptifs et créer un graphique adapté.","Présenter une conclusion en distinguant observation et interprétation."],"prerequisites":"Aucun prérequis en statistiques. Savoir utiliser les fonctions de base d’un tableur est un plus.","chapters":[
    {"title":"Comprendre les données","description":"Définir la question avant de calculer ou de représenter.","lessons":[["Formuler une question d’analyse","Préciser population, période, mesure et décision que l’analyse doit éclairer."],["Lire un jeu de données","Identifier lignes, colonnes, types de valeurs, unités et granularité."],["Repérer les défauts de qualité","Détecter valeurs manquantes, doublons, formats incohérents et anomalies possibles."]]},{"title":"Nettoyer et organiser","description":"Préparer un tableau fiable et réutilisable.","lessons":[["Uniformiser les formats","Harmoniser dates, catégories, espaces et types sans effacer l’information utile."],["Traiter les valeurs manquantes","Choisir entre correction, exclusion ou signalement selon la question étudiée."],["Documenter les transformations","Garder une trace des règles appliquées pour rendre l’analyse reproductible."]]},{"title":"Calculer et visualiser","description":"Résumer les données et choisir une représentation lisible.","lessons":[["Calculer des indicateurs descriptifs","Utiliser effectifs, proportions, moyenne et médiane selon la forme des données."],["Comparer des catégories","Construire un tableau croisé simple et interpréter les écarts observés."],["Choisir un graphique adapté","Associer barres, lignes ou distribution à la question sans déformer les échelles."]]},{"title":"Présenter une analyse","description":"Relier résultats, limites et recommandations prudentes.","lessons":[["Séparer faits et interprétations","Écrire ce que les données montrent puis distinguer les explications possibles."],["Vérifier les résultats","Recalculer un indicateur et contrôler qu’un filtre ou une unité n’a pas faussé le résultat."],["Projet : tableau de bord de suivi","Créer un tableau de bord simple avec indicateurs, graphiques, commentaire et limites des données."]]}
  ]},
  {"code":"SEC-01","subtitle":"Adopter les gestes essentiels pour protéger ses comptes et ses appareils.","description":"Un parcours de sensibilisation à la cybersécurité couvrant mots de passe, hameçonnage, mises à jour, sauvegardes et réaction face à un incident courant.","outcomes":["Reconnaître des signaux d’hameçonnage et vérifier une demande.","Mettre en place une authentification plus sûre.","Réduire les risques liés aux appareils et aux mises à jour.","Suivre une procédure simple de sauvegarde et de réaction."],"prerequisites":"Aucun prérequis technique. Les exercices utilisent des scénarios fictifs et des paramètres de compte de démonstration.","chapters":[
    {"title":"Menaces et réflexes de base","description":"Comprendre les risques courants pour les personnes et petites équipes.","lessons":[["Identifier les actifs à protéger","Lister comptes, appareils, fichiers et services dont la perte aurait un impact."],["Reconnaître l’hameçonnage","Examiner expéditeur, urgence, liens et pièces jointes avant toute action."],["Vérifier une demande inhabituelle","Confirmer par un canal connu avant de transmettre une information ou d’effectuer un paiement."]]},{"title":"Comptes et authentification","description":"Réduire les risques de compromission des accès numériques.","lessons":[["Créer des mots de passe robustes","Éviter la réutilisation et utiliser un gestionnaire de mots de passe reconnu."],["Activer la double authentification","Choisir une méthode supplémentaire et conserver les codes de récupération."],["Gérer les accès d’une équipe","Appliquer le principe du moindre privilège et retirer les accès devenus inutiles."]]},{"title":"Appareils et données","description":"Maintenir les appareils à jour et préserver des copies de secours.","lessons":[["Installer les mises à jour","Comprendre leur rôle et planifier l’installation depuis les sources officielles."],["Protéger les fichiers importants","Classer les données, limiter le partage et choisir des emplacements de stockage adaptés."],["Tester une sauvegarde","Vérifier qu’une copie existe et qu’un fichier peut réellement être restauré."]]},{"title":"Réagir à un incident","description":"Limiter les conséquences et conserver les informations utiles.","lessons":[["Isoler un appareil suspect","Déconnecter l’équipement si nécessaire et éviter d’effacer les traces avant consigne."],["Réinitialiser un compte compromis","Utiliser un appareil sûr, changer les accès et révoquer les sessions inconnues."],["Projet : plan de sécurité personnel","Créer une checklist de protection, sauvegarde et réaction pour un compte ou une petite équipe."]]}
  ]},
  {"code":"ENT-01","subtitle":"Structurer le lancement d’une activité numérique autour d’un besoin réel.","description":"Un parcours de démarrage entrepreneurial pour valider un problème, préciser une offre, tester un modèle économique simple et préparer un plan d’action réaliste.","outcomes":["Décrire un segment client et un problème à résoudre.","Tester une hypothèse de marché avec des retours concrets.","Formuler une offre et estimer ses coûts essentiels.","Construire un plan de lancement avec des indicateurs simples."],"prerequisites":"Aucun prérequis. Une idée de service ou de produit numérique est utile, mais peut être choisie pendant la formation.","chapters":[
    {"title":"Partir d’un besoin client","description":"Éviter de construire une offre avant de comprendre le problème.","lessons":[["Choisir un problème à explorer","Décrire une difficulté fréquente, ses conséquences et les solutions déjà utilisées."],["Définir un premier segment","Délimiter un groupe de personnes ayant un contexte et un besoin comparables."],["Préparer des entretiens de découverte","Écrire des questions ouvertes pour comprendre les pratiques sans vendre trop tôt."]]},{"title":"Valider une offre","description":"Tester la pertinence de la solution et clarifier sa promesse.","lessons":[["Formuler une proposition de valeur","Relier public, problème, résultat attendu et approche proposée."],["Créer un test simple","Choisir une maquette, une page ou une démonstration qui permet d’obtenir un retour."],["Analyser les retours","Classer faits, objections et demandes pour décider quoi modifier ou poursuivre."]]},{"title":"Modèle économique et opérations","description":"Estimer les ressources nécessaires et le chemin vers les premières ventes.","lessons":[["Lister coûts et ressources","Distinguer coûts ponctuels, récurrents, outils, temps et dépendances externes."],["Construire un prix de départ","Comparer coûts, valeur perçue et alternatives en documentant les hypothèses."],["Décrire un parcours de vente","Cartographier découverte, échange, paiement, livraison et accompagnement."]]},{"title":"Préparer le lancement","description":"Organiser les premières étapes et apprendre à partir des résultats.","lessons":[["Choisir des indicateurs de départ","Suivre quelques mesures reliées aux conversations, conversions et coûts."],["Planifier un lancement léger","Définir actions, responsables, échéances et critères de poursuite."],["Projet : fiche de lancement","Présenter problème, cible, offre, hypothèses, budget de départ et plan d’expérimentation."]]}
  ]},
  {"code":"CAR-01","subtitle":"Concevoir un portfolio qui rend ses compétences et ses projets faciles à évaluer.","description":"Apprendre à sélectionner ses réalisations, raconter sa démarche et publier une présentation professionnelle adaptée à des clients ou recruteurs du numérique.","outcomes":["Choisir un positionnement et un public pour son portfolio.","Présenter un projet avec contexte, démarche et résultat.","Organiser une navigation courte et lisible.","Vérifier puis partager un portfolio professionnel."],"prerequisites":"Aucun prérequis. Des projets d’étude, personnels ou professionnels peuvent servir de matière première.","chapters":[
    {"title":"Positionnement et sélection","description":"Clarifier la direction professionnelle avant de rassembler des travaux.","lessons":[["Définir son public cible","Identifier les personnes qui consulteront le portfolio et les critères qui comptent pour elles."],["Choisir les projets à présenter","Sélectionner des travaux pertinents et expliquer honnêtement son rôle dans chacun."],["Formuler une présentation concise","Rédiger une introduction qui relie spécialité, valeur apportée et types de missions recherchées."]]},{"title":"Raconter ses réalisations","description":"Transformer une galerie de travaux en preuves compréhensibles.","lessons":[["Présenter le contexte d’un projet","Décrire besoin, contraintes, équipe et périmètre sans divulguer d’informations confidentielles."],["Expliquer sa démarche","Montrer étapes, décisions et compromis avec des éléments visuels utiles."],["Décrire les résultats avec précision","Distinguer résultats mesurés, livrables obtenus et apprentissages personnels."]]},{"title":"Construire le portfolio","description":"Organiser une expérience claire sur ordinateur et mobile.","lessons":[["Établir une arborescence simple","Organiser accueil, projets, profil et contact en fonction des besoins du lecteur."],["Rédiger des fiches projet","Structurer chaque cas avec rôle, démarche, livrables et leçons apprises."],["Rendre le contact facile","Ajouter une prochaine étape claire et tester les liens et coordonnées."]]},{"title":"Publier et faire évoluer","description":"Contrôler la qualité, partager le portfolio et le tenir à jour.","lessons":[["Relire et vérifier les droits","Contrôler textes, liens, confidentialité, autorisations d’images et informations personnelles."],["Adapter son portfolio à une candidature","Choisir les projets et l’ordre de présentation selon une offre ou une mission ciblée."],["Projet : portfolio prêt à partager","Assembler une page d’accueil, trois fiches projet et une méthode de mise à jour régulière."]]}
  ]}
]
  $catalog$::jsonb;
  v_spec jsonb;
  v_chapter jsonb;
  v_lesson jsonb;
  v_course record;
  v_version uuid;
  v_chapter_id uuid;
  v_lesson_id uuid;
  v_question_id uuid;
  v_chapter_position integer;
  v_lesson_position integer;
  v_minutes integer;
  v_lesson_type public.lesson_type;
  v_body text;
  v_options jsonb;
begin
  for v_spec in select value from jsonb_array_elements(v_catalog)
  loop
    select id, current_version_id, draft_version_id, status
      into v_course from public.courses where code = v_spec->>'code' for update;
    if not found then raise exception 'Formation pilote introuvable : %', v_spec->>'code'; end if;
    if v_course.status = 'published' and v_course.draft_version_id is null then
      raise exception 'La formation % est déjà publiée; crée une version de travail avant de la modifier', v_spec->>'code';
    end if;
    v_version := coalesce(v_course.draft_version_id, v_course.current_version_id);
    if v_version is null or not exists(select 1 from public.course_versions where id=v_version and course_id=v_course.id and status='draft') then
      raise exception 'Version de travail manquante pour %', v_spec->>'code';
    end if;

    update public.courses set
      subtitle = v_spec->>'subtitle',
      short_description = v_spec->>'description',
      description = v_spec->>'description',
      description_md = v_spec->>'description',
      prerequisites_md = v_spec->>'prerequisites',
      learning_outcomes = v_spec->'outcomes',
      level = 'beginner'::public.course_level,
      content_source = 'original',
      license_notes = 'Contenus pédagogiques originaux préparés pour le pilote Nova Digital.',
      syllabus = v_spec->'chapters'
    where id = v_course.id;

    v_minutes := 0;
    v_chapter_position := 0;
    for v_chapter in select value from jsonb_array_elements(v_spec->'chapters')
    loop
      v_chapter_position := v_chapter_position + 1;
      insert into public.course_chapters(course_id, version_id, position, title, description)
      values(v_course.id, v_version, v_chapter_position, v_chapter->>'title', v_chapter->>'description')
      on conflict(version_id, position) do update set title=excluded.title, description=excluded.description
      returning id into v_chapter_id;

      v_lesson_position := 0;
      for v_lesson in select value from jsonb_array_elements(v_chapter->'lessons')
      loop
        v_lesson_position := v_lesson_position + 1;
        v_lesson_type := case
          when v_chapter_position = 4 and v_lesson_position = 3 then 'project'::public.lesson_type
          when v_lesson_position = 3 then 'quiz'::public.lesson_type
          when v_lesson_position = 2 then 'exercise'::public.lesson_type
          else 'text'::public.lesson_type end;
        insert into public.course_lessons(
          chapter_id, course_id, position, title, lesson_type, duration_minutes, summary,
          is_free_preview, preview_requires_login, published
        ) values(
          v_chapter_id, v_course.id, v_lesson_position, v_lesson->>0, v_lesson_type,
          case when v_lesson_type='project' then 45 when v_lesson_type='quiz' then 15 when v_lesson_type='exercise' then 25 else 20 end,
          v_lesson->>1, v_chapter_position=1 and v_lesson_position<=2, false, true
        )
        on conflict(chapter_id, position) do update set
          title=excluded.title, lesson_type=excluded.lesson_type, duration_minutes=excluded.duration_minutes,
          summary=excluded.summary, is_free_preview=excluded.is_free_preview,
          preview_requires_login=excluded.preview_requires_login, published=excluded.published
        returning id into v_lesson_id;

        v_minutes := v_minutes + case when v_lesson_type='project' then 45 when v_lesson_type='quiz' then 15 when v_lesson_type='exercise' then 25 else 20 end;
        v_body := format(
          E'## Résultat attendu\n%s\n\n## Méthode\n1. Clarifie le besoin et les contraintes avant de choisir une solution.\n2. Applique les étapes du cours en gardant une trace de tes décisions.\n3. Contrôle le résultat avec un critère observable et corrige ce qui ne répond pas au besoin.\n\n## Mise en pratique\n%s\n\n## À retenir\nLe livrable doit être compréhensible, vérifiable et adapté au contexte de la personne qui l’utilisera.',
          v_lesson->>1, v_lesson->>1
        );
        insert into public.course_lesson_contents(lesson_id, body_md, project_instructions)
        values(v_lesson_id, v_body, case when v_lesson_type in ('exercise','project') then
          format('Réalise l’activité « %s ». Livrable attendu : une production ou une checklist qui montre les étapes suivies. Vérifie la précision, la cohérence et l’adaptation au contexte avant de soumettre.', v_lesson->>0)
          else null end)
        on conflict(lesson_id) do update set body_md=excluded.body_md, project_instructions=excluded.project_instructions;

        if v_lesson_type='quiz' then
          v_options := jsonb_build_array(
            jsonb_build_object('id','a','label','Suivre la méthode, puis vérifier le résultat avec des critères adaptés.'),
            jsonb_build_object('id','b','label','Choisir un outil avant de clarifier le besoin et ne pas contrôler le résultat.'),
            jsonb_build_object('id','c','label','Reprendre une solution sans l’adapter au contexte ni documenter les décisions.')
          );
          insert into public.quiz_questions(lesson_id, position, prompt_md, options)
          values(v_lesson_id, 1, format('Pour « %s », quelle démarche permet d’obtenir un résultat fiable ?', v_lesson->>0), v_options)
          on conflict(lesson_id, position) do update set prompt_md=excluded.prompt_md, options=excluded.options
          returning id into v_question_id;
          insert into public.quiz_answer_keys(question_id, correct_option_ids, explanation_md)
          values(v_question_id, '["a"]'::jsonb, format('La méthode consiste à appliquer les étapes de « %s » puis à vérifier le livrable avec des critères observables.', v_lesson->>0))
          on conflict(question_id) do update set correct_option_ids=excluded.correct_option_ids, explanation_md=excluded.explanation_md;
        end if;
      end loop;
    end loop;
    update public.courses set estimated_minutes=v_minutes where id=v_course.id;
  end loop;
end
$pilot$;
